function resolveFetch(opts?: ClientOptions): typeof fetch {
  return opts?.fetch ?? globalThis.fetch.bind(globalThis)
}

function resolveBase(opts?: ClientOptions): string {
  const b = opts?.baseUrl ?? ''
  return b.endsWith('/') ? b.slice(0, -1) : b
}

async function postJson<T>(
  path: string,
  body: object,
  opts?: ClientOptions,
): Promise<T> {
  const f = resolveFetch(opts)
  const url = `${resolveBase(opts)}${path}`
  const res = await f(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json' },
    body: JSON.stringify(body ?? {}),
    cache: 'no-store',
  })
  const json = (await res.json().catch(() => ({}))) as {
    code?: string
    message?: string
  } & T
  if (!res.ok || (json as { code?: string }).code) {
    const msg =
      (typeof (json as { message?: string }).message === 'string' &&
        (json as { message?: string }).message) ||
      `Connect ${path} failed (${res.status})`
    throw new Error(msg)
  }
  return json as T
}

/** Typed unary call by service/method (generated transport). */
export async function callRpc(
  service: string,
  method: string,
  body: object = {},
  opts?: ClientOptions,
): Promise<JsonObject> {
  return postJson<JsonObject>(`/sail.ops.v1.${service}/${method}`, body, opts)
}

/** Alias kept for session call-sites / tests (`ops(service, method, body)`). */
export const ops = callRpc

/** Health is a bare GET endpoint (not unary Service/Method). */
export async function opsHealth(opts?: ClientOptions): Promise<HealthRet> {
  const f = resolveFetch(opts)
  const res = await f(`${resolveBase(opts)}/sail.ops.v1.health`, { cache: 'no-store' })
  const json = (await res.json().catch(() => ({}))) as HealthRet
  if (!res.ok) throw new Error(`health failed (${res.status})`)
  return json
}

