/**
 * Subscribe to ops watch channel (SSE `GET /sail.ops.v1.watch`).
 * Returns an unsubscribe function.
 */
export function watch(
  filter: WatchFilter,
  cb: (ev: WatchEvent) => void,
  opts?: ClientOptions,
): () => void {
  const params = new URLSearchParams()
  if (filter.kinds?.length) params.set('kinds', filter.kinds.join(','))
  if (filter.pathPrefix) params.set('pathPrefix', filter.pathPrefix)
  const q = params.toString()
  const url = `${resolveBase(opts)}/sail.ops.v1.watch${q ? `?${q}` : ''}`
  const es = new EventSource(url)
  const onMessage = (msg: MessageEvent) => {
    try {
      const ev = JSON.parse(String(msg.data)) as WatchEvent
      if (filter.kinds?.length && !filter.kinds.includes(ev.kind)) return
      if (filter.pathPrefix && !ev.path.startsWith(filter.pathPrefix)) return
      cb(ev)
    } catch {
      /* ignore malformed */
    }
  }
  es.addEventListener('message', onMessage)
  es.onmessage = onMessage
  return () => {
    es.removeEventListener('message', onMessage)
    es.close()
  }
}
